using Godot;
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using HakutaiKagami.Core.Contracts;
public partial class StartSelectionPanel
{
    string DelegationCase=>OS.GetCmdlineUserArgs().FirstOrDefault(a=>a.StartsWith("--delegation-case="))?[18..]??"success";
    string DelegationOutput=>ProjectSettings.GlobalizePath("res://../Docs/Design/DelegationMissionV1/runtime-local/"+DelegationCase);
    void DelegationAdvance(long at){while(stage!.HubSession.Seconds<at){long before=stage.HubSession.Seconds;stage.HubAdvance(at);Need(stage.HubSession.Seconds>before,"delegation UI clock advances");}}
    RegionalCommand DelegationCommand=>stage!.HubSession.DiagnosticSnapshot().Region!.Commands.Single(c=>c.Request.Recipient==ContractFixture.Clerk);
    long DelegationDue(string message){var w=stage!.HubSession.DiagnosticSnapshot();return w.Region!.Deliveries.Single(d=>w.Messaging.Attempts.Single(a=>a.Id==d.Attempt).MessageId==message).DueAt;}
    string DelegationAck=>stage!.HubSession.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="region-report"&&m.CorrelationId==DelegationCommand.Request.Id.Value).Id;
    long DelegationArrive=>stage!.HubSession.DiagnosticSnapshot().Delegation!.Plans.Single().Units.SelectMany(u=>u.Route).Select(l=>l.EndAt).DefaultIfEmpty(stage.HubSession.Seconds).Max();
    void DelegationStep(int n){var child=stage!;if(n==0){child.HubPress("delegate-line");child.HubPress("delegate-focus");}if(n==1){DelegationAdvance(DelegationDue(DelegationCommand.Message));Need(DelegationMission.View(child.HubSession,child.HubSession.PlayerControl).Single().Receipt=="発送済・結果未確認","private receipt result remains unknown before reply");}if(n==2)DelegationAdvance(DelegationDue(DelegationAck));if(n==3)DelegationAdvance(DelegationCase=="success"?Math.Max(child.HubSession.Seconds,DelegationArrive):child.HubSession.Seconds+1);if(n==4)DelegationAdvance(DelegationCase=="success"?DelegationDue(child.HubSession.DiagnosticSnapshot().Delegation!.Arrivals.Single().Message):child.HubSession.Seconds+9);}
    void DelegationContinue(int checkpoint){for(int n=checkpoint+1;n<5;n++)DelegationStep(n);DelegationAdvance(stage!.HubSession.Seconds+1);}
    async Task DelegationCapture(string name){await Frame();GetViewport().GetTexture().GetImage().SavePng(DelegationOutput+"/diagnostic.png");Need(stage!.HubFits(),"delegation controls and minimum3D fit actual viewport");GetViewport().GetTexture().GetImage().SavePng(DelegationOutput+"/"+name+".png");File.WriteAllText(DelegationOutput+"/"+name+"-rect.json",System.Text.Json.JsonSerializer.Serialize(stage.HubRect()));}
    async Task RunDelegationSelectionChecks(){Directory.CreateDirectory(DelegationOutput);((TabContainer)GetParent()).CurrentTab=2;await Frame();if(SelectionMode.EndsWith("restore")){ScanProfiles();int i=profiles.FindIndex(p=>p.Profile.Instance==File.ReadAllText(DelegationOutput+"/origin-instance.txt"));Need(i>=0,"delegation profile listed after process restart");saved.Select(i);Press(load);await Frame();for(int n=0;n<5;n++){stage!.HubLoad("delegation-s"+n);File.WriteAllText(DelegationOutput+"/restored-s"+n+"-pose.json",stage.HubPose());Need(stage.HubPose()==File.ReadAllText(DelegationOutput+"/s"+n+"-pose.json"),"delegation plan/known result/model exact restore "+n);await DelegationCapture("restored-s"+n);DelegationContinue(n);await DelegationCapture("continued-s"+n);}}
        else{role.Select(6);nameInput.Text="検証共同演習";Press(begin);await Frame();Need(stage!=null&&DelegationMission.Enabled(stage.HubSession.DiagnosticSnapshot()),"actual start dropdown opens temporary other-house command");var profile=ContractJson.Read<SavedStartProfile>(File.ReadAllBytes(Path.Combine(CurrentDirectory,"start-profile.json")));File.WriteAllText(DelegationOutput+"/origin-instance.txt",profile.Instance);for(int n=0;n<5;n++){DelegationStep(n);stage!.HubSession.SetPaused(true);stage.HubSave("delegation-s"+n);File.WriteAllText(DelegationOutput+"/s"+n+"-pose.json",stage.HubPose());await DelegationCapture("s"+n);}DelegationContinue(4);stage!.HubPress("save");await DelegationCapture("final");var w=stage.HubSession.DiagnosticSnapshot();var row=DelegationMission.View(stage.HubSession,stage.HubSession.PlayerControl).Single();Need(row.Receipt==(DelegationCase=="success"?"applied":DelegationCase=="refuse"?"refused":"authority-refused"),"actual delivered receipt result matches scenario");Need(w.Delegation!.Arrivals.Length==(DelegationCase=="success"?1:0),"arrival is reported only after actual placement");Need(w.Units.Where(u=>u.Commander==ContractFixture.Clerk).All(u=>u.Organization==new EntityId("org:house")),"other-house ownership survives actual orders");}
        File.WriteAllText(DelegationOutput+"/"+(SelectionMode.EndsWith("restore")?"restore":"check")+"-checks.json",System.Text.Json.JsonSerializer.Serialize(checks));GD.Print("DELEGATION_MISSION_PASSED");GetTree().Quit();}
}
